import string


def gen(rng):
    def names(count, maxlen):
        seen = set()
        out = []
        while len(out) < count:
            s = ''.join(rng.choice(string.ascii_lowercase) for _ in range(rng.randint(1, maxlen)))
            if s not in seen:
                seen.add(s)
                out.append(s)
        return out

    def make(n, maxlen, order='shuffle'):
        cs = names(n + 1, maxlen)
        paths = [(cs[i], cs[i + 1]) for i in range(n)]
        if order == 'shuffle':
            rng.shuffle(paths)
        elif order == 'reverse':
            paths.reverse()
        return str(n) + '\n' + '\n'.join(f'{a} {b}' for a, b in paths)

    tests = ['1\na b', '1\nb a', '2\na b\nb c', '2\nb c\na b', '3\nparis rome\nberlin paris\nrome oslo',
             '4\nd e\nc d\nb c\na b', '2\nzzzzzzzz yyyyyyyy\nxxxxxxxx zzzzzzzz']
    for n in (2, 3, 4, 5, 8, 12, 20, 40):
        tests.append(make(n, 3))
        tests.append(make(n, 8, 'reverse'))
    tests.append(make(1000, 8))
    tests.append(make(100000, 8))
    tests.append(make(100000, 8, 'reverse'))
    tests.append(make(100000, 8, 'forward'))
    return tests

